style.css:
@-moz-document domain("depop.com") {
/* ============================================================
     Depop is a React SPA with content-hashed class names
     (styles_*, template_*, baseFilterStyles_*, sharedStyles_*).
     A :root design-token layer exists (--surface-*, --text-*),
     but almost every surface and text colour is still hardcoded
     white / #f3f3f3 / #efefef / #d7d7d7 / #000 / #262626, so the
     tokens are not a usable single point of remap. We retheme via
     STABLE hooks only — semantic tags, ARIA roles, data-testid
     attributes, module-name class fragments and structural
     relationships. The base palette flows through html/body;
     opaque dark surfaces are re-established on the sticky header,
     filter bar, dropdowns, mobile drawers and footer so nothing
     bleeds through. Depop's brand red is preserved as identity
     but toned for dark, and the design system's semantic button
     colours (green/blue/yellow/facebook, disabled) are kept
     distinct from it.
     ============================================================ */

  :root {
    color-scheme: dark;
  }

  /* ---- Base ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }

  /* Soften every light border into a subtle dark line */
  * {
    border-color: #262c33 !important;
  }

  /* ---- Typography: re-light dark hardcoded text on dark ---- */
  h1, h2, h3, h4, h5, h6 {
    color: #e6edf3 !important;
  }

  p,
  span,
  li,
  label,
  dd,
  dt,
  figcaption,
  blockquote,
  td,
  th {
    color: #c4cdd6 !important;
  }

  a {
    color: #c4cdd6 !important;
  }

  a:hover {
    color: #e6edf3 !important;
  }

  /* ============================================================
     Header / nav — real sticky banner, re-establish opaque dark
     ============================================================ */
  header,
  [role="banner"],
  [data-testid="header"] {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  header a,
  [role="banner"] a,
  [data-testid="header"] button {
    color: #e6edf3 !important;
  }

  header *,
  [role="banner"] * {
    color: #e6edf3 !important;
  }

  /* The "Sale" category-nav item is the ONE accent item in the nav:
     the site paints it via an inline `--textColor:#E20020` custom
     property. The blanket banner-text rule above flattens it to the
     same white as Women/Men/Kids, erasing the only colour signal in
     the nav. Restore it, toned for dark. */
  [role="banner"] [style*="--textColor"],
  [role="banner"] [style*="--textColor"] * {
    color: #ff6b7d !important;
  }

  /* When the Sale category is hovered/open the site fills its trigger with a
     solid red pill (its inline --hoverBg:#E20020) and flips the label white —
     the one emphasised nav affordance. Our generic menuitem/expanded hover
     (grey #262c33) outranks the banner-button reset and flattened it, so
     hovering Sale looked identical to hovering Women/Men. Restore a toned red
     fill; the higher-specificity selector beats [role="menuitem"]:hover. */
  [role="banner"] [style*="--hoverBg:#E20020"]:hover,
  [role="banner"] [style*="--hoverBg:#E20020"][aria-expanded="true"] {
    background-color: #d1304a !important;
  }

  [role="banner"] [style*="--hoverBg:#E20020"]:hover,
  [role="banner"] [style*="--hoverBg:#E20020"]:hover *,
  [role="banner"] [style*="--hoverBg:#E20020"][aria-expanded="true"],
  [role="banner"] [style*="--hoverBg:#E20020"][aria-expanded="true"] * {
    color: #ffffff !important;
  }

  /* The header's icon for the page you are ON (Likes / Bag) is tinted
     #2960af — the only "you are here" indicator in the chrome. The
     banner-text rule painted it the same white as the inactive icons. */
  [role="banner"] [class*="navigationLink--active"],
  [role="banner"] [class*="navigationLink--active"] *,
  a[class*="navigationLink--active"],
  a[class*="navigationLink--active"] * {
    color: #6ea8fe !important;
  }

  /* Category nav buttons (Women / Men / Kids / Brands ...) and the
     header's inner containers sit on white pills — flatten to dark */
  [role="banner"] button {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  /* Nav containers (era/age pill rows, hero nav) carry white
     backgrounds outside <header> too — flatten them onto the page */
  nav {
    background-color: transparent !important;
  }

  /* Homepage Buy/Sell segmented toggle — the sliding active "thumb"
     paints a LIGHT linear-gradient (rgb(251,246,241)→rgb(226,232,247))
     via background-image, invisible to a bg-COLOR reset → it renders a
     pale pill on the dark hero. Drop the gradient and give the active
     segment an elevated dark surface so it still reads as selected. */
  nav span[class*="thumb"] {
    background-image: none !important;
    background-color: #30363d !important;
    border-color: #2d333b !important;
  }

  /* The MOBILE nav drawer's app-download promo paints the same light
     linear-gradient (rgb(251,246,241)→rgb(226,232,247)) as the hero toggle,
     via background-IMAGE over a transparent background-color — so it survives
     every bg-colour reset and renders a near-white slab in the dark drawer,
     with its "Buy, sell & discover on the go" label light-on-light. The card
     only exists once the drawer is opened, so no load-time scan reaches it.
     appDownloadBox is the <a> wrapper; the gradient sits on an inner card div,
     and the label/badge boxes inside it are *Container elements that the
     header-container rule above would otherwise paint a second, darker tone —
     cover all three so the promo reads as one flat surface. */
  [class*="appDownloadBox"],
  [class*="appDownloadBox"] [class*="card"],
  [class*="appDownloadBox"] [class*="Container"] {
    background-image: none !important;
    background-color: #1c2128 !important;
  }

  /* "Shop by category" hover mega-menu — rendered OUTSIDE the
     banner (its own hoverContainer), floating: keep it opaque dark
     so the category links don't sit on a white panel. */
  [class*="hoverContainer"],
  [class*="hoverMenu"],
  header div[class*="Container"],
  [role="banner"] div[class*="Container"] {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  [class*="hoverContainer"] *,
  [class*="hoverMenu"] * {
    color: #c4cdd6 !important;
    background-color: transparent !important;
  }

  /* The mega-menu's "Featured" tiles overlay their caption ('80s,
     Carhartt, Crochet...) directly ON a light product photo, where
     the site paints it #262626. The blanket menu-text rule above
     re-lights it to #c4cdd6 → light-on-light, unreadable. Photos are
     image content we must not touch, so restore the original dark
     caption for captions inside an image container only (the plain
     dark-panel menu links keep the light colour). */
  [class*="featuredImageContainer"] [class*="descriptionText"] {
    color: #262626 !important;
    -webkit-text-fill-color: #262626 !important;
  }

  /* ============================================================
     Global search bar + dropdown
     ============================================================ */
  input,
  textarea,
  select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* Custom "On sale" filter checkbox: the visible box is an
     appearance:none input's ::before painted solid white — a
     pseudo-element surface the element-bg scan can't see. Darken
     the box; a checkmark drawn black is handled by the svg rule. */
  input[type="checkbox"]::before {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ...but the CHECKED box is natively filled #2960af and the
     DISABLED one #d7d7d7. Flattening all three to the same
     #1c2128 leaves checked/unchecked/disabled visually identical
     apart from the tick glyph. Keep the state colours. */
  input[type="checkbox"]:checked::before {
    background-color: #2960af !important;
    border-color: #2960af !important;
  }

  input[type="checkbox"]:disabled::before {
    background-color: #30363d !important;
    border-color: #30363d !important;
  }

  /* The style-quiz modal's answer radios are 24px <span>s the site fills solid
     white with a #262626 inner dot for the selected one — on its white modal an
     unselected radio reads as an empty ring, the selected one as a filled dot.
     Left alone on dark, that inverts: every unselected radio is a glaring white
     disc and the SELECTED one is the only dimmed circle. Too small (24px) for a
     size-filtered surface scan and portaled outside <main>, so nothing but a
     rendered pixel shows it. Keep the empty/full reading: dark disc + grey ring
     unselected, light dot inside an accented ring when selected. Must stay
     ABOVE the radioIndicatorError rule further down, which only overrides the
     border and would otherwise lose the tie on equal specificity. */
  [class*="radioIndicator"] {
    background-color: #1c2128 !important;
    border-color: #4a525b !important;
  }

  [class*="radioIndicatorSelected"] {
    border-color: #e6edf3 !important;
  }

  [class*="radioIndicatorSelected"]::after {
    background-color: #e6edf3 !important;
  }

  [data-testid="searchBar__input"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  [data-testid="searchBar__input"]::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* "CLEAR" is a filled grey pill (#747474, white label) — the search bar's only
     affordance for wiping the query. The blanket `[role="banner"] button`
     transparent reset flattens it to bare text, so it stops reading as a control.
     Its native fill is achromatic, so the chroma diff cannot see the loss. */
  [class*="searchBarButtons"] [class*="clearButton"] {
    background-color: #4a525b !important;
    color: #ffffff !important;
  }

  [class*="searchBarButtons"] [class*="clearButton"]:hover {
    background-color: #5c656f !important;
  }

  /* The search submit arrow keeps the UA default `border-style: outset` with a
     TRANSPARENT border-color, so the site draws nothing. The blanket `*`
     border-color reset at the top of the file gives it an opaque colour, and
     `outset` derives a 3D bevel from that — a bright light-steel box appears
     around the arrow, poking out of the search pill. Only visible once the field
     has focus/content, which is why a load-time scan never framed it. */
  [class*="searchBarButtons"] [class*="submitButton"] {
    border-color: transparent !important;
  }

  /* Search autocomplete / suggestion dropdown — keep opaque */
  [role="listbox"],
  [role="menu"],
  [role="dialog"],
  [role="combobox"] ul,
  ul[id*="listbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  [role="option"],
  [role="menuitem"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  [role="option"]:hover,
  [role="menuitem"]:hover {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Main content area + filter / sort bar
     ------------------------------------------------------------
     Depop's result/filter containers carry hardcoded-white divs
     with no stable hook. Inside <main> nothing has an intentional
     surface colour (cards sit directly on the page), so we blank
     every container background to transparent and let the dark
     body show through, then re-skin the interactive controls.
     ============================================================ */
  main,
  main div,
  main section,
  [role="main"],
  [role="main"] div {
    background-color: transparent !important;
  }

  /* The homepage hero (and similar promo bands) paint a LIGHT
     linear-gradient via background-image — invisible to a plain
     background-color reset. Drop the light gradient so the band
     sits on the dark page; keep its inner photo intact. */
  main section[class*="ero"],
  [class*="homepageHero"],
  [class*="HomepageHero"],
  [class*="heroBanner"],
  [class*="promoBanner"],
  [class*="quizEntryPoint"] {
    background-image: none !important;
    background-color: transparent !important;
  }

  button {
    color: #e6edf3 !important;
  }

  /* Filter / sort trigger pills and dropdown buttons.
     NOT [aria-haspopup]: Depop puts aria-haspopup="dialog" on plain
     text and icon controls (every product card's heart, the profile
     follower counts, the message icon, the seller-rating stars), so
     that selector boxed them all in an opaque #1c2128 square painted
     over the product photo. [aria-expanded] marks the real
     disclosure triggers; the trigger classes cover the rest. */
  [aria-expanded] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Filter dropdown panels / popovers */
  [class*="dropdown"],
  [class*="Dropdown"],
  [class*="popover"],
  [class*="Popover"],
  [class*="menu"],
  [class*="Menu"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* The panel rule above wins over the site's own light hover
     (#eaeaea) on filter options, leaving them with no hover
     feedback at all. Give the rows a dark hover back. */
  [class*="FilterDropdownOption"]:hover,
  [class*="searchFilterCheckbox"]:hover {
    background-color: #262c33 !important;
  }

  /* The category filter's collapsible group headers (Men / Women / Kids /
     Everything else) paint a light #eaeaea hover fill — a click-only nested
     surface no load-time scan reaches. On dark, the pale label then sits
     light-on-light. Give the row a dark elevated hover instead. */
  [class*="collapsibleRow"]:hover {
    background-color: #262c33 !important;
  }

  /* The MOBILE product page pins a position:fixed action bar (price + Make offer /
     Add to bag) to the bottom of the viewport, painted #fff. It lives inside
     <main>, so the blanket `main div` transparent reset above makes it fully
     see-through: the product grid scrolls visibly behind the buttons and the
     bar's own price is unreadable over the photos. It exists only under the
     mobile breakpoint, so a desktop-only pass never renders it. Both selectors
     resolve to the same node — the inline `bottom` is what pins the bar — and
     the other containers they match already sit on the page base. */
  [class*="productInfo"] > div > div[class*="container"],
  [class*="productInfo"] div[style*="bottom"] {
    background-color: #14181d !important;
  }

  /* The mobile "Filter" drawer is a position:fixed, full-viewport
     panel painted #fff — and it lives inside <main>, so the blanket
     `main div` transparent reset above makes it fully see-through:
     the product grid scrolls visibly behind its title, options and
     "Clear all / View items" footer. Re-establish an opaque base. */
  [class*="filtersContainer"] {
    background-color: #14181d !important;
  }

  [class*="filtersContainer"] [class*="footer"] {
    background-color: #14181d !important;
    color: #8b949e !important;
  }

  /* Colour swatch dots take their fill from an inline
     `--background-color` (multi-colour options use `--background-image`).
     The blanket `main div` transparent reset above wipes every dot, so
     the whole colour list renders as bare labels. Re-assert the site's
     own custom properties and give each dot a ring so the near-black
     swatch stays visible on the dark panel. The SAME pattern is used by
     the PDP's colour attribute under a different class name
     (colourCircle) — fixing only the filter left the PDP dot erased. */
  main [class*="colourFilterColourSpot"],
  main [class*="colourCircle"] {
    background-color: var(--background-color) !important;
    background-image: var(--background-image) !important;
    border: 1px solid #4a525b !important;
  }

  /* Category / popular "pill" chips, filter chips and active-filter
     tags inside the results area carry hardcoded-white fills →
     elevated dark. (activeFilter = the removable "Women / Dresses"
     applied-filter tag.) Match the CONTROLS only: the bare
     [class*="pill"] / [class*="activeFilter"] / [class*="FilterTrigger"]
     forms also matched their plain <div> wrappers
     (popularPillsContainer, pillsContainer, activeFiltersContainer) and
     painted a grey slab behind each chip row, plus the <p> and <svg>
     inside every trigger. */
  main button[class*="pill"],
  main button[class*="Pill"],
  main a[class*="pill"],
  main a[class*="Pill"],
  [class*="badgePill"],
  button[class*="chip"],
  button[class*="Chip"],
  button[class*="activeFilter"],
  button[class*="FilterTrigger"],
  label[class*="FilterTrigger"],
  button[class*="FilterButton"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  button[class*="activeFilter"] * {
    color: #c4cdd6 !important;
  }

  /* badgePill's glyph is #262626 — legible on its native #f3f3f3 fill,
     invisible once the pill above turns dark. */
  [class*="badgeIcon"] {
    color: #c4cdd6 !important;
  }

  main button[class*="pill"]:hover,
  main button[class*="Pill"]:hover,
  main a[class*="pill"]:hover,
  main a[class*="Pill"]:hover,
  button[class*="chip"]:hover,
  button[class*="Chip"]:hover,
  button[class*="activeFilter"]:hover,
  button[class*="FilterTrigger"]:hover,
  label[class*="FilterTrigger"]:hover,
  button[class*="FilterButton"]:hover {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* Depop separates content with 1px #d7d7d7 <hr>s and 6px #d7d7d7
     dot separators; the "or" row on the login page draws its two arms
     as ::before/::after borders (a pseudo — the `*` border reset above
     structurally cannot reach it). All three render as bright rules
     across the dark page. */
  hr {
    background-color: #262c33 !important;
    border-color: #262c33 !important;
  }

  /* The profile's Shop/Likes tab strip draws its sliding active-tab indicator as
     an <hr> filled #262626 — near-black ink on the white page, the strongest
     mark in the component. The divider rule above catches it by tag and leaves
     it the exact colour of the full-width rule it sits on, so no tab looks
     selected. Both colours are achromatic, so the chroma diff is blind to it. */
  hr[class*="tabHighlight"] {
    background-color: #e6edf3 !important;
    border-color: #e6edf3 !important;
  }

  [class*="divider"]::before,
  [class*="divider"]::after {
    border-color: #262c33 !important;
  }

  [class*="dotDivider"] {
    background-color: #4a525b !important;
  }

  /* ============================================================
     Product result cards / grid
     ============================================================ */
  a[href*="/products/"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Price text on cards + PDP — keep bright/legible */
  a[href*="/products/"] p,
  a[href*="/products/"] span {
    color: #e6edf3 !important;
  }

  /* On a discounted card the site mutes the struck-through original
     price (#747474) against a strong current price (#262626). Both
     land on #c4cdd6 here, flattening the distinction — mute the
     struck-through one back. */
  [class*="discountedFullPrice"],
  [class*="originalPrice"] {
    color: #8b949e !important;
  }

  /* The "SOLD" / "RESERVED" overlay stamped across a sold listing's
     photo is the site's one yellow signal (#ffda0a). The card-price
     rule directly above outranks a bare class selector, so it was
     repainting the stamp plain white — a sold item then reads exactly
     like an available one. */
  [class*="soldText"],
  a[href*="/products/"] [class*="soldText"] {
    color: #ffda0a !important;
    -webkit-text-fill-color: #ffda0a !important;
  }

  /* ============================================================
     Product detail page (PDP)
     ============================================================ */
  /* Image gallery stage + thumbnails: keep wrappers dark so no
     white container leaks around photos */
  [data-testid="mobile"],
  [data-testid="desktop"],
  [class*="Image"],
  [class*="image"],
  [class*="gallery"],
  [class*="Gallery"],
  [class*="carousel"],
  [class*="Carousel"] {
    background-color: transparent !important;
  }

  /* Loading skeletons — the PDP buy-box renders its CTA pills (Buy now /
     Make offer / Add to bag) and the two wishlist/share circles over the
     image as shimmer placeholders during hydration, and the same component
     skins the breadcrumb, gallery, attribute and grid-card placeholders.
     Every one carries a "shimmerStyles" module class and paints a LIGHT
     animated gradient (#d3d3d3 → #eee) as a background-IMAGE over a
     transparent background-color — so it survives every bg-COLOUR reset and
     flashes bright white on the dark page. Repaint the sweep in elevated
     dark tones; the placeholderShimmer keyframes animate background-position,
     which we leave intact, so the shimmer still moves. */
  [class*="shimmerStyles"],
  [class*="Skeleton"],
  [class*="skeleton"] {
    background-image: linear-gradient(90deg, #1c2128 0px, #2d333b 20%, #1c2128 40%, #1c2128) !important;
    background-color: #1c2128 !important;
  }

  /* Price */
  [data-testid="productPrimaryAttributes"],
  [data-testid="productPrimaryAttributes"] * {
    color: #e6edf3 !important;
  }

  /* Description "show more" expander: the collapsed description's
     inline "show more" link paints a horizontal scroll-fade behind
     itself via ::after — linear-gradient(90deg, rgba(255,255,255,0),
     #fff 30%) — so the truncated last line fades into a WHITE strip
     (a bg-IMAGE gradient the bg-color audit can't see). Re-fade it to
     the dark page base instead. */
  [class*="showMoreButton"]::after {
    background-image: linear-gradient(90deg, rgba(20, 24, 29, 0), rgb(20, 24, 29) 30%) !important;
  }

  /* NO surface rule for [data-testid^="segment--"] or
     [data-testid="productCard__sizeAttr"]. Both testids now mark plain
     transparent text nodes, not pills: segment--* is a full-width (1248x735)
     PDP recommendation carousel section ("You might also like", "Items from
     Nike"...) and productCard__sizeAttr is the bare size line under every grid
     card. Giving either an elevated fill paints four page-wide grey bands down
     the PDP plus a grey bar behind every card's size. The PDP's own meta line
     is [data-testid="productPrimaryAttributes"] (coloured below); the size line
     inherits the p/span text colour. */

  /* Seller card / avatar block */
  [data-testid="avatar"] {
    background-color: #1c2128 !important;
  }

  /* Seller rating "feedback" link (★★★★★ (6)) on PDP + profile.
     Its review count sits in a <div class="_caption-sm-bold"> coloured
     #747474 (dark-on-dark) that the p/span text rules don't reach;
     lighten the whole control so the stars and count stay legible, and
     keep the inline link free of any button surface. */
  [class*="feedbackButton"] {
    background-color: transparent !important;
    border-color: transparent !important;
  }

  [class*="feedbackButton"] * {
    color: #c4cdd6 !important;
  }

  /* "See more" on the description and the login page's link-buttons are
     the site's only blue (#2960af) affordance; the generic link/text
     rules flattened them to the same grey as body copy. */
  [class*="seeMoreText"],
  [class*="seeMoreText"] *,
  [class*="buttonLinkWrapperVariant"],
  [class*="buttonLinkWrapperVariant"] *,
  [class*="buttonLinkTextVariant"],
  [class*="buttonLinkTextVariant"] * {
    color: #6ea8fe !important;
  }

  /* Like / save / interaction buttons (icon + count) */
  [data-testid^="productInteraction__"],
  [data-testid^="productInteraction__"] * {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* The PDP's buyer-protection shield and shipping truck, and the footer's
     X / Instagram / TikTok badges, are SVGs whose paths are fill/stroke
     "currentColor" over a hardcoded dark `color` (#262626 and pure #000).
     They were legible on the site's white page and render dark-on-dark here —
     an icon-only failure no element-background scan can see. Their own colour
     is the single point of repair. */
  [class*="bannerContainer"] svg,
  [class*="shippingIcon"],
  footer [class*="socialLink"] svg,
  [data-testid="footerV2"] [class*="socialLink"] svg {
    color: #c4cdd6 !important;
  }

  /* The TikTok badge is the exception in that row: its path carries a literal
     fill="black" ATTRIBUTE rather than currentColor, so re-lighting the svg's
     colour leaves it a black glyph on the dark surface. The same social row
     appears both in the footer and in the MOBILE nav drawer (its own
     socialLink module hash, outside <footer>/<nav>) — scope to the class, not
     the footer, so the drawer's TikTok is lit too. */
  [class*="socialLink"] path[fill="black"] {
    fill: #c4cdd6 !important;
  }

  /* The homepage hero's three trust signals (Buy safely / 49M+ / 500K+) paint
     their glyphs with a `fill` of #43484d — a mid-grey that read fine on the
     site's white hero and drops to ~1.9:1 on the dark one, leaving each label
     with a barely-there icon. `fill` beats `color` here, so the icon rules
     above cannot reach them. */
  [class*="trustSignal"] svg,
  [class*="trustSignal"] svg path {
    fill: #8b949e !important;
  }

  /* ...and the third signal ("Buy safely / Depop Protection") is a link the site
     fills rgba(255,255,255,0.3) — invisible over its own white hero, a mid-grey
     slab over the dark one. Translucent white never trips a near-white surface
     scan, which reads the alpha-less channels only. Give it a real elevated
     card so it still reads as the one tappable signal of the three. */
  a[class*="trustSignalLink"] {
    background-color: #1c2128 !important;
  }

  /* ============================================================
     Buttons — Depop renders its design-system buttons as
     <button>/<span>/<a> carrying a "buttonWrapper" module class
     with hardcoded white/light fills (Sign up, Log in, Buy now,
     Make offer...). Re-skin those pills to an elevated dark
     surface; the primary submit/CTA takes the Depop red.
     ============================================================ */
  /* Outline / secondary pills (Make offer, Add to bag-secondary,
     Log in) → elevated dark surface */
  [class*="buttonWrapper"][class*="outl"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  [class*="buttonWrapper"][class*="outl"]:hover {
    background-color: #262c33 !important;
  }

  /* Solid / primary pills (Buy now, Sell now, primary Add to bag)
     carry Depop's high-emphasis fill → the brand red, toned */
  [class*="buttonWrapper"]:not([class*="outl"]),
  button[type="submit"] {
    background-color: #d1304a !important;
    color: #ffffff !important;
    border-color: transparent !important;
  }

  [class*="buttonWrapper"]:not([class*="outl"]):hover,
  button[type="submit"]:hover {
    background-color: #f1556a !important;
  }

  [class*="buttonWrapper"]:not([class*="outl"]) * {
    color: #ffffff !important;
  }

  [class*="buttonWrapper"][class*="outl"] * {
    color: #e6edf3 !important;
  }

  /* The header's "Sign up" and "Log in" reuse the button component but
     override it to a white fill: signup keeps the 2px border (reads as
     an outline button), login drops it (reads as a plain text link).
     Neither carries an "outl" class, so the solid rule above painted
     BOTH the same red as "Sell now" — three identical red pills where
     the site has a clear primary / secondary / tertiary ladder. */
  [class*="buttonWrapper"][class*="textButton--"],
  [class*="buttonWrapper"][class*="textButton--"] * {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  [class*="buttonWrapper"][class*="textButton--login"] {
    border-color: transparent !important;
  }

  [class*="buttonWrapper"][class*="textButton--signup"] {
    border-color: #4a525b !important;
  }

  [class*="buttonWrapper"][class*="textButton--"]:hover {
    background-color: #262c33 !important;
  }

  /* "Continue with Apple" on /login and /magic-link is a solid BLACK pill (white
     Apple glyph + white label) — Apple's brand-mandated button, and the login
     page's second CTA. Its fill sits on the wrapper that carries the pill radius,
     inside <main>, so the blanket `main div` transparent reset erased it: the
     label and glyph then float bare on the page with no button surface at all,
     while the Google option beside it keeps its pill. Restore the black fill and
     ring it with an inset shadow (no layout change) so the pill reads on the
     near-black page. */
  [class*="ssoLoginOptionsContainer"] [class*="wrapper"] {
    background-color: #000000 !important;
    box-shadow: inset 0 0 0 1px #3a4149 !important;
  }

  [class*="appleButton"],
  [class*="appleButton"] * {
    color: #ffffff !important;
  }

  /* The button component also ships SEMANTIC solid variants and a
     disabled state, none of which carry an "outl" class — so the solid
     rule above swallowed every one of them into the primary red. A
     disabled button then looks exactly like an enabled brand CTA.
     Restore each variant's own hue, toned for dark. */
  [class*="buttonWrapper"][class*="colorStyles--green"] {
    background-color: #2f7d24 !important;
    border-color: #2f7d24 !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--blue"] {
    background-color: #2960af !important;
    border-color: #2960af !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--facebook"] {
    background-color: #4a66a0 !important;
    border-color: #4a66a0 !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--yellow"] {
    background-color: #ffda0a !important;
    border-color: #ffda0a !important;
    color: #262626 !important;
  }

  [class*="buttonWrapper"][class*="colorStyles--yellow"] * {
    color: #262626 !important;
  }

  [class*="buttonWrapper"]:disabled {
    background-color: #30363d !important;
    border-color: #30363d !important;
    color: #8b949e !important;
  }

  [class*="buttonWrapper"]:disabled * {
    color: #8b949e !important;
  }

  /* Outline variants tint only their label; the outline-text rule above
     flattens all of them to the same grey. */
  [class*="buttonWrapper"][class*="outline--green"] * {
    color: #56b04a !important;
  }

  [class*="buttonWrapper"][class*="outline--blue"] * {
    color: #6ea8fe !important;
  }

  [class*="buttonWrapper"][class*="outline--yellow"] * {
    color: #ffda0a !important;
  }

  /* Depop's design system paints its text ACTIONS in an indigo (#3d37bd):
     the search bar's "Clear all", the autocomplete's category suggestions
     ("...in Men's Footwear"), "See similar items", the toast/tips links and
     the modal dismiss + delete actions. The generic a/button/span text rules
     above flatten every one of them to the same grey as body copy, so an
     action reads as inert text. Restore the accent, toned for dark.
     (sellerWebsite is the profile bio's site link — the site's other blue,
     #2960af; same treatment.) */
  [class*="resetAllButton"],
  [class*="resetAllButton"] *,
  [class*="dismissModalButton"],
  [class*="deleteText"],
  [class*="categorySuggestionText"],
  [class*="seeSimilarItemsText"],
  [class*="toastLink"],
  [class*="tipsLink"],
  [class*="todoButton"],
  [class*="ctaWrapper"] a,
  [class*="sellerWebsite"] {
    color: #6ea8fe !important;
  }

  /* Depop "Sale" / red accents — tone the raw #e20020 for dark */
  [style*="226, 0, 32"],
  [class*="sale"],
  [class*="Sale"] {
    color: #ff6b7d !important;
  }

  /* #e20020 is not only the brand accent — it is also Depop's ERROR colour.
     Every form validation message (login, the price filter's "Minimum price
     can't be higher than maximum price", offer alerts) is painted with it,
     and the blanket p/span/label rule repaints them the same grey as body
     copy: the error then reads as ordinary help text. Restore the alert red. */
  [class*="errorText"],
  [class*="errorMessage"],
  [class*="ErrorMessage"],
  [class*="errorMessage"] *,
  [class*="lightTextError"],
  [class*="zeroLeftWarning"],
  [class*="offerAlertText"],
  [class*="offersToReview"],
  [class*="rejectedOfferTitle"] {
    color: #ff6b7d !important;
  }

  /* ...and the input that error points at is outlined in the same red, which
     the blanket `*` border reset at the top of the file erased — leaving the
     offending field visually identical to a valid one. */
  [class*="priceFilterInputError"],
  [class*="inputContainerError"],
  [class*="descriptionErrorBorder"],
  [class*="radioIndicatorError"] {
    border-color: #ff6b7d !important;
    outline-color: #ff6b7d !important;
  }

  /* The seller bio and the listing description render their links in the brand
     red; the blanket `a` rule greyed them into the surrounding copy. */
  [class*="shopBio"] a,
  [class*="description"] a {
    color: #ff6b7d !important;
  }

  /* "Free domestic shipping" is the PDP's one positive signal — icon AND label
     are green (#266d1c). The icon inherits its own colour and stayed green, but
     the blanket `p` rule greyed the LABEL beside it: a half-erased signal that
     looks like an ordinary line of metadata. */
  [class*="shippingMessage"] {
    color: #56b04a !important;
  }

  /* The "50% OFF" discount badge keeps its solid red fill, but the
     generic span/p text rule repaints its label #c4cdd6 — ~3.3:1 on
     that red, under the 4.5 the original white label cleared. Restore
     white on the badge only. */
  [class*="discountLabel"],
  [class*="discountLabel"] * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* The homepage style-quiz modal renders in a portal (outside <main>)
     and its progress track keeps a hardcoded #f3f3f3 fill. At 8px tall
     it slips every size-filtered surface scan while rendering as a
     bright bar across the dark modal. Darken the track; the red
     progress fill inside it stays Depop red. */
  [class*="progressionBarContainer"] {
    background-color: #30363d !important;
  }

  /* ============================================================
     Footer
     ============================================================ */
  footer,
  [data-testid="footerV2"],
  footer div,
  [data-testid="footerV2"] div {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  footer a,
  [data-testid="footerV2"] a {
    color: #c4cdd6 !important;
  }

  footer a:hover,
  [data-testid="footerV2"] a:hover {
    color: #e6edf3 !important;
  }

  /* ============================================================
     SVG icons that were black → readable on dark
     ============================================================ */
  svg[fill="#000000"],
  svg[fill="#000"],
  svg[fill="black"] {
    fill: #e6edf3 !important;
  }
}
